const TASK_TYPE_DETECTION_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    detected_task_type: {
      type: Type.STRING,
      description: 'Must be one of "document", "agent", "application", or "image".',
      enum: ['document', 'agent', 'application', 'image'],
    },
  },
  required: ['detected_task_type'],
};

export const detectTaskType = async (text: string): Promise<'document' | 'agent' | 'application' | 'image'> => {
  const systemInstruction = `
You are an expert project analyst. Classify the user's input into: "document", "agent", "application", or "image".

CRITICAL DISTINCTION RULES:
- **agent**: Use this for OPERATIONAL instructions. If the user wants to create a BOT, AUTOMATION, or a SYSTEM that performs tasks (e.g., "buat agen", "rancang workflow", "pemicu", "bot trading", "asisten otomatis"). Keywords: agen, bot, workflow, alur kerja, automate, trigger, pemicu, asisten, monitor.
- **document**: Use this for STATIC CONTENT generation. If the user wants to write an article, report, or SOP *about* something, but not the automation logic itself. Keywords: tulis, artikel, laporan, SOP, rangkum, brief.
- **application**: Use this for BUILDING SOFTWARE/UI. Keywords: app, website, fitur, UI, database, DApp.
- **image**: Use this for VISUAL EDITS. Keywords: edit foto, ganti background, gambar, visual.

If the user says "Agen" or "Asisten" in ANY context related to tasks, prioritize "agent".
`;
  const MAX_LENGTH = 8000;
  const truncatedText = text.length > MAX_LENGTH ? text.substring(0, MAX_LENGTH) + "..." : text;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Tentukan jenis tugas untuk input ini: "${truncatedText}"`,
      config: {
        systemInstruction,
        responseMimeType: 'application/json',
        responseSchema: TASK_TYPE_DETECTION_SCHEMA,
      },
    });
    const parsed = JSON.parse(response.text || '{"detected_task_type":"document"}');
    return parsed.detected_task_type;
  } catch (error) {
    console.error("Task type detection error:", error);
    return 'document';
  }
};


