const META_PROMPT_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    summary: { type: Type.STRING },
    techniques: { type: Type.STRING },
    mainPrompt: { type: Type.STRING },
    variantA: { type: Type.STRING },
    variantB: { type: Type.STRING },
    uiSpec: { type: Type.STRING },
    checklist: { type: Type.STRING },
    example: { type: Type.STRING },
  },
  required: ['summary', 'techniques', 'mainPrompt', 'variantA', 'variantB', 'uiSpec', 'checklist', 'example'],
};

export const detectTaskType = async (text: string): Promise<string> => {
  const systemInstruction = `
You are a Senior Project Classifier. Categorize the input into one of: "document", "agent", "application", "image", "video", "audio", "presentation".

CRITICAL ACCURACY RULES:
1. **AGENT**: Priority #1. If the user mentions "agen", "bot", "asisten", "workflow", "otomasi", "pemicu", "trigger", "monitor", "execute", "logic", or asks for a system that "DOES something" over time.
2. **DOCUMENT**: Only if the goal is writing content (article, report, summary, SOP text) WITHOUT operational logic.
3. **PRESENTATION**: Keywords: "slide", "deck", "ppt", "presentasi", "outline slide".
4. **VIDEO**: Keywords: "video", "sora", "film", "animasi", "motion", "kamera".
5. **AUDIO**: Keywords: "lagu", "musik", "suno", "audio", "genre", "vokal".

If there is ANY doubt between Document and Agent, choose "agent" if there are verbs like "handle", "process", or "automate".
`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Classify this input: "${text.substring(0, 4000)}"`,
      config: {
        systemInstruction,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: { detected_type: { type: Type.STRING } },
          required: ['detected_type']
        }
      },
    });
    const parsed = JSON.parse(response.text || '{"detected_type":"document"}');
    return parsed.detected_type;
  } catch (error) {
    return 'document';
  }
};

export const generateMetaPrompt = async (formData: FormData): Promise<ParsedOutput> => {
  const model = 'gemini-3-pro-preview';
  const userPrompt = `## FORM DATA\n${JSON.stringify(formData, null, 2)}`;

  try {
    const response = await ai.models.generateContent({
        model,
        contents: userPrompt,
        config: {
            systemInstruction: SYSTEM_PROMPT,
            responseMimeType: "application/json",
            responseSchema: META_PROMPT_SCHEMA,
            thinkingConfig: { thinkingBudget: 16384 }
        }
    });
    return JSON.parse(response.text || '{}') as ParsedOutput;
  } catch (error) {
    console.error("API Error:", error);
    throw error;
  }
};

