                                      <button type="button" onClick={() => removeContext(index)} disabled={isAnalyzing} className="text-gray-400 hover:text-red-400 ml-2 p-1 rounded-full hover:bg-gray-600 transition"><XCircleIcon className="h-4 w-4" /></button>
