  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { type FormData, type ParsedOutput, type CodeAnalysisResult } from "../types";
import { SYSTEM_PROMPT, FORM_STEPS } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const META_PROMPT_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    summary: { type: Type.STRING },
    techniques: { type: Type.STRING },
    mainPrompt: { type: Type.STRING },
    variantA: { type: Type.STRING },
    variantB: { type: Type.STRING },
    uiSpec: { type: Type.STRING },
    checklist: { type: Type.STRING },
    example: { type: Type.STRING },
  },
  required: ['summary', 'techniques', 'mainPrompt', 'variantA', 'variantB', 'uiSpec', 'checklist', 'example'],
};

/**
 * Pembersih JSON untuk menangani output AI yang mungkin mengandung markdown atau teks tambahan.
 */
const sanitizeJsonResponse = (text: string): string => {
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  return jsonMatch ? jsonMatch[0] : "{}";
};

/**
 * Menghasilkan deskripsi skema field yang sangat ketat untuk prompt AI.
 */
const getDetailedSchemaForTask = (taskType: string): string => {
    const relevantSteps = FORM_STEPS.filter(s => s.id === 'prefs' || s.id === `${taskType}_details`);
    let schemaDescription = `WAJIB GUNAKAN ID BERIKUT SEBAGAI KEY JSON:\n`;

    relevantSteps.forEach(step => {
        step.fields.forEach(f => {
            let fieldInfo = `- Key: "${f.id}" (Deskripsi: ${f.label})`;
            if (f.options) {
                const opts = f.options.map(o => typeof o === 'string' ? o : o.value);
                fieldInfo += ` | NILAI HARUS SALAH SATU DARI: [${opts.join(', ')}]`;
            }
            schemaDescription += fieldInfo + "\n";
        });
    });
    return schemaDescription;
};

export const detectTaskType = async (text: string): Promise<string> => {
  const systemInstruction = `Kategorikan proyek ke dalam salah satu: "document", "agent", "application", "image", "video", "audio", "presentation".
- agent: bot, asisten, otomatisasi alur kerja.
- application: spesifikasi software, desain UI/UX.
- video: skrip film, promosi video, gerakan kamera.
Output: {"detected_type": "kategori"}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Klasifikasikan: "${text.substring(0, 3000)}"`,
      config: {
        systemInstruction,
        responseMimeType: 'application/json',
      },
    });
    const parsed = JSON.parse(response.text || '{"detected_type":"document"}');
    return parsed.detected_type;
  } catch (error) {
    return 'document';
  }
};

export const generateMetaPrompt = async (formData: FormData): Promise<ParsedOutput> => {
  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `## FORM DATA\n${JSON.stringify(formData, null, 2)}`,
        config: {
            systemInstruction: SYSTEM_PROMPT,
            responseMimeType: "application/json",
            responseSchema: META_PROMPT_SCHEMA,
            thinkingConfig: { thinkingBudget: 16384 }
        }
    });
    return JSON.parse(response.text || '{}') as ParsedOutput;
  } catch (error) {
    throw new Error("Gagal menghasilkan Meta-Prompt. Periksa koneksi atau kuota API.");
  }
};

export const detectPreferences = async (text: string): Promise<Partial<FormData>> => {
  const systemInstruction = `Ekstrak preferensi pengguna ke dalam nilai valid:
- creativity_level/risk_tolerance: "rendah", "sedang", "tinggi"
- security_level: "standar", "ketat (OWASP)", "enterprise"
- language: "id", "en"
Gunakan Bahasa Indonesia.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Konteks: ${text}`,
      config: {
        systemInstruction,
        responseMimeType: 'application/json',
      }
    });
    return JSON.parse(sanitizeJsonResponse(response.text));
  } catch {
    return {};
  }
};

export const extractInfoFromDocument = async (text: string, taskType: string): Promise<Partial<FormData>> => {
    const schema = getDetailedSchemaForTask(taskType);
    const systemInstruction = `Tugas: Isi formulir untuk proyek "${taskType}".
ATURAN:
1. GUNAKAN BAHASA INDONESIA.
2. GUNAKAN KEY JSON SESUAI ID FIELD DI BAWAH.
3. JANGAN JAWAB DALAM BAHASA INGGRIS.
4. UNTUK OPSI (ENUM), PILIH YANG TERSEDIA DI DAFTAR.

SKEMA FIELD:
${schema}`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `DOKUMEN:\n${text}`,
            config: { systemInstruction, responseMimeType: 'application/json' }
        });
        return JSON.parse(sanitizeJsonResponse(response.text));
    } catch (error) {
        console.error("Extraction error:", error);
        return {};
    }
};

export const extractInfoWithInstruction = async (text: string, instruction: string, taskType: string): Promise<Partial<FormData>> => {
    const schema = getDetailedSchemaForTask(taskType);
    const systemInstruction = `Ikuti instruksi: "${instruction}" untuk mengisi form "${taskType}".
Gunakan Bahasa Indonesia dan format JSON sesuai skema berikut:
${schema}`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `KONTEN:\n${text}`,
            config: { systemInstruction, responseMimeType: 'application/json' }
        });
        return JSON.parse(sanitizeJsonResponse(response.text));
    } catch {
        return {};
    }
};

export const extractInfoFromIdea = async (instruction: string, taskType: string): Promise<Partial<FormData>> => {
    const schema = getDetailedSchemaForTask(taskType);
    const systemInstruction = `Ubah ide proyek menjadi JSON.
Skema:
${schema}`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `IDE: "${instruction}"`,
            config: { systemInstruction, responseMimeType: 'application/json' }
        });
        return JSON.parse(sanitizeJsonResponse(response.text));
    } catch {
        return {};
    }
};

export const analyzeCode = async (code: string): Promise<CodeAnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Analisislah kode ini (Bahasa Indonesia):\n\n${code}`,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            functions: { type: Type.ARRAY, items: { type: Type.STRING } },
            classes: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ['summary', 'functions', 'classes'],
        }
      }
    });
    return JSON.parse(response.text || '{}') as CodeAnalysisResult;
  } catch {
    return { summary: "Analisis gagal.", functions: [], classes: [] };
  }
};

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { FORM_STEPS } from './constants';
import { type FormData, type ParsedOutput, type FormFieldData } from './types';
import { generateMetaPrompt, extractInfoFromDocument, extractInfoWithInstruction, extractInfoFromIdea, detectTaskType, detectPreferences, analyzeCode } from './services/geminiService';
import { parseFile } from './services/fileParser';
import Step from './components/Step';
import Preview from './components/Preview';
import Placeholder from './components/Placeholder';
import SkeletonPreview from './components/SkeletonPreview';
import { LoaderIcon, AlertTriangleIcon, SparklesIcon, UploadIcon, PencilIcon, XCircleIcon, CodeBracketIcon } from './components/icons';

// Initial state creator
const createInitialState = (): FormData => {
    const initialState: FormData = {};
    FORM_STEPS.forEach(step => {
      step.fields.forEach(field => {
        if (field.type === 'checkbox') {
          initialState[field.id] = field.default ?? [];
        } else if (field.type === 'image_upload' || field.type === 'file_upload') {
          initialState[field.id] = null;
        } else {
          initialState[field.id] = field.default ?? '';
        }
      });
    });
    return initialState;
};

type TaskType = 'document' | 'agent' | 'application' | 'image' | 'video' | 'audio' | 'presentation';

const fileToBase64 = (file: File): Promise<{ base64: string, mimeType: string }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      const base64 = result.split(',')[1];
      if (!base64) {
          reject(new Error("Gagal mengonversi file."));
          return;
      }
      resolve({ base64, mimeType: file.type });
    };
    reader.onerror = error => reject(error);
  });
};

const isCodeFile = (file: File): boolean => {
    const codeExtensions = ['sol', 'js', 'ts', 'py', 'json'];
    const extension = file.name.split('.').pop()?.toLowerCase();
    return !!extension && codeExtensions.includes(extension);
};

const App: React.FC = () => {
  const [formData, setFormData] = useState<FormData>(createInitialState);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [output, setOutput] = useState<ParsedOutput | null>(null);
  const [submissionCount, setSubmissionCount] = useState(0);

  // AI Quick Fill States
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [analysisInstruction, setAnalysisInstruction] = useState('');
  const [pastedContexts, setPastedContexts] = useState<string[]>([]);
  const [currentContextInput, setCurrentContextInput] = useState(''); 
  const [filesToAnalyze, setFilesToAnalyze] = useState<File[]>([]);
  const [needsConfirmation, setNeedsConfirmation] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<{ textForAnalysis: string, fileTextContent: string, hasFiles: boolean, hasInstruction: boolean, detectedTaskType: TaskType } | null>(null);
  const [autoFillCompleted, setAutoFillCompleted] = useState(false);

  const prevTaskTypeRef = useRef<string | any>(formData.task_type);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const taskSpecificFields = useMemo(() => {
    const map: Record<string, string[]> = {};
    FORM_STEPS.forEach(s => {
        if (s.id.includes('_details')) {
            const type = s.id.split('_')[0];
            map[type] = s.fields.map(f => f.id);
        }
    });
    return map;
  }, []);

  useEffect(() => {
    const currentTaskType = formData.task_type as string;
    const prevTaskType = prevTaskTypeRef.current;
    if (prevTaskType && prevTaskType !== currentTaskType) {
      const fieldsToClear = taskSpecificFields[prevTaskType] || [];
      if (fieldsToClear.length > 0) {
        setFormData(prev => {
          const newData = { ...prev };
          const defaults = createInitialState();
          fieldsToClear.forEach(id => newData[id] = defaults[id]);
          return newData;
        });
      }
    }
    prevTaskTypeRef.current = currentTaskType;
  }, [formData.task_type, taskSpecificFields]);

  const handleFormChange = useCallback((id: string, value: any) => {
    setFormData(prev => ({ ...prev, [id]: value }));
  }, []);

  const proceedWithExtraction = async (confirmedTaskType: TaskType) => {
      if (!analysisResult) return;
      setIsAnalyzing(true);
      setNeedsConfirmation(false);
      const { textForAnalysis, fileTextContent, hasFiles, hasInstruction } = analysisResult;

      try {
          const detectedPrefs = await detectPreferences(textForAnalysis);
          let extractedData: Partial<FormData> = {};

          if (hasFiles && hasInstruction) {
            extractedData = await extractInfoWithInstruction(fileTextContent, analysisInstruction, confirmedTaskType);
          } else if (hasFiles) {
            extractedData = await extractInfoFromDocument(fileTextContent, confirmedTaskType);
          } else if (hasInstruction) {
            extractedData = await extractInfoFromIdea(analysisInstruction, confirmedTaskType);
          }

          const codeFile = filesToAnalyze.find(isCodeFile);
          let codeData: any = {};
          if (codeFile && (confirmedTaskType === 'agent' || confirmedTaskType === 'application')) {
              const codeContent = await parseFile(codeFile);
              const analysis = await analyzeCode(codeContent);
              codeData.code_analysis_summary = analysis.summary;
              if (confirmedTaskType === 'agent') {
                  codeData.agent_context = `Analisis Kode:\nFunctions: ${analysis.functions.join(', ')}`;
              }
          }

          // INTEGRITY CHECK: Gunakan state awal baru lalu timpa dengan hasil AI
          const baseState = createInitialState();
          setFormData({
              ...baseState,
              task_type: confirmedTaskType,
              ...detectedPrefs,
              ...extractedData,
              ...codeData
          });
          setAutoFillCompleted(true);
      } catch (err: any) {
          setAnalysisError("Gagal sinkronisasi data.");
      } finally {
          setIsAnalyzing(false);
          setAnalysisResult(null);
      }
  }

  const handleAutoFill = async () => {
    const tempContexts = [...pastedContexts];
    if (currentContextInput.trim()) tempContexts.push(currentContextInput.trim());

    if (filesToAnalyze.length === 0 && !analysisInstruction.trim() && tempContexts.length === 0) {
      setAnalysisError("Berikan input untuk dianalisis.");
      return;
    }

    setIsAnalyzing(true);
    setAnalysisError(null);
    try {
      let fileTextContent = '';
      if (filesToAnalyze.length > 0) {
        const results = await Promise.all(filesToAnalyze.map(f => parseFile(f)));
        fileTextContent = results.join('\n\n');
      }
      const textForAnalysis = fileTextContent + '\n' + tempContexts.join('\n') + '\n' + analysisInstruction;
      const detectedTaskType = await detectTaskType(textForAnalysis) as TaskType;

      setAnalysisResult({ 
          textForAnalysis, 
          fileTextContent, 
          hasFiles: (filesToAnalyze.length > 0 || tempContexts.length > 0), 
          hasInstruction: !!analysisInstruction.trim(), 
          detectedTaskType 
      });
      setNeedsConfirmation(true);
    } catch (err: any) {
      setAnalysisError("Analisis dokumen gagal.");
      setIsAnalyzing(false);
    }
  };

  const handleSubmit = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const payload = { ...formData };
      const result = await generateMetaPrompt(payload);
      setOutput(result); 
      setSubmissionCount(prev => prev + 1);
    } catch (e: any) { 
      setError(e.message); 
    } finally { 
      setIsLoading(false); 
    }
  };

  const resetAutoFill = () => { setAutoFillCompleted(false); setFilesToAnalyze([]); setPastedContexts([]); setCurrentContextInput(''); setAnalysisInstruction(''); };

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 p-4 sm:p-8 font-sans">
      <div className="max-w-7xl mx-auto">
        <header className="text-center mb-10">
          <h1 className="text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-500">Meta-Prompt Generator</h1>
          <p className="text-gray-400 mt-2">Arsitektur Prompt Industrial dengan Validasi Keamanan.</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          <div className="bg-gray-800/50 rounded-2xl p-6 border border-gray-700 h-fit sticky top-8">
            <div className="bg-gray-700/30 rounded-lg mb-8 p-4 space-y-4">
                <h2 className="font-bold text-xl text-indigo-400 flex items-center"><SparklesIcon className="mr-2 h-5 w-5"/>Isi Cepat dengan AI</h2>

                {!autoFillCompleted ? (
                  <>
                  {needsConfirmation && analysisResult ? (
                      <div className="bg-indigo-900/30 p-4 rounded-lg border border-indigo-700">
                          <h3 className="font-semibold">Konfirmasi Kategori</h3>
                          <p className="text-sm text-indigo-200 mt-1">Sistem mendeteksi kategori: <strong>{analysisResult.detectedTaskType}</strong>. Benar?</p>
                          <div className="mt-4 flex gap-2">
                              <button onClick={() => handleConfirmation(analysisResult.detectedTaskType)} className="flex-1 bg-green-600 py-2 rounded-md font-bold">Ya</button>
                              <button onClick={() => setNeedsConfirmation(false)} className="flex-1 bg-gray-600 py-2 rounded-md">Bukan</button>
                          </div>
                      </div>
                  ) : (
                    <div className="space-y-4">
                        <textarea value={analysisInstruction} onChange={(e) => setAnalysisInstruction(e.target.value)} placeholder="Tulis instruksi atau ide di sini..." className="w-full bg-gray-700 border border-gray-600 rounded-md p-3 text-sm h-24" />
                        <div className="flex gap-2">
                            <button onClick={() => fileInputRef.current?.click()} className="flex-1 border border-dashed border-gray-500 py-2 rounded-md text-sm text-gray-400 hover:bg-gray-700">Unggah File</button>
                            <input ref={fileInputRef} type="file" className="hidden" onChange={(e) => e.target.files && setFilesToAnalyze(Array.from(e.target.files))} multiple />
                        </div>
                        <button onClick={handleAutoFill} disabled={isAnalyzing} className="w-full bg-indigo-600 py-3 rounded-lg font-bold flex justify-center items-center">
                            {isAnalyzing ? <LoaderIcon className="mr-2"/> : <SparklesIcon className="mr-2 h-5 w-5"/>} 
                            {isAnalyzing ? "Menganalisis..." : "Isi Formulir Otomatis"}
                        </button>
                    </div>
                  )}
                  </>
                ) : (
                  <div className="bg-green-900/30 p-4 rounded-lg border border-green-700 flex justify-between items-center">
                      <span className="text-green-300 font-medium">✅ Form terisi otomatis!</span>
                      <button onClick={resetAutoFill} className="text-xs bg-green-700 px-2 py-1 rounded">Reset AI</button>
                  </div>
                )}
                {analysisError && <p className="text-red-400 text-xs mt-2">{analysisError}</p>}
            </div>

            <form onSubmit={(e) => { e.preventDefault(); handleSubmit(); }} className="space-y-6">
              {FORM_STEPS.filter(s => !s.showIf || formData[s.showIf.field] === s.showIf.value).map(step => (
                <Step key={step.id} stepData={step} formData={formData} onFormChange={handleFormChange} />
              ))}
              <div className="flex gap-4 pt-6 border-t border-gray-700">
                <button type="button" onClick={() => setFormData(createInitialState())} className="flex-1 py-3 border border-gray-600 rounded-lg">Reset</button>
                <button type="submit" disabled={isLoading} className="flex-[2] bg-green-600 py-3 rounded-lg font-bold">
                    {isLoading ? "Memproses..." : "Hasilkan Meta-Prompt"}
                </button>
              </div>
            </form>
          </div>

          <div className="min-h-[500px]">
            {isLoading ? <SkeletonPreview /> : output ? <Preview data={output} taskType={formData.task_type as string} /> : <Placeholder />}
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { FORM_STEPS } from './constants';
import { type FormData, type ParsedOutput, type FormFieldData } from './types';
import { generateMetaPrompt, extractInfoFromDocument, extractInfoWithInstruction, extractInfoFromIdea, detectTaskType, detectPreferences, analyzeCode } from './services/geminiService';
import { parseFile } from './services/fileParser';
import Step from './components/Step';
import Preview from './components/Preview';
import Placeholder from './components/Placeholder';
import SkeletonPreview from './components/SkeletonPreview';
import { LoaderIcon, AlertTriangleIcon, SparklesIcon, UploadIcon, PencilIcon, XCircleIcon, CodeBracketIcon } from './components/icons';

// Initial state creator
const createInitialState = (): FormData => {
    const initialState: FormData = {};
    FORM_STEPS.forEach(step => {
      step.fields.forEach(field => {
        if (field.type === 'checkbox') {
          initialState[field.id] = field.default ?? [];
        } else if (field.type === 'image_upload' || field.type === 'file_upload') {
          initialState[field.id] = null;
        } else {
          initialState[field.id] = field.default ?? '';
        }
      });
    });
    return initialState;
};

type TaskType = 'document' | 'agent' | 'application' | 'image' | 'video' | 'audio' | 'presentation';

const fileToBase64 = (file: File): Promise<{ base64: string, mimeType: string }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      const base64 = result.split(',')[1];
      if (!base64) {
          reject(new Error("Gagal mengonversi file."));
          return;
      }
      resolve({ base64, mimeType: file.type });
    };
    reader.onerror = error => reject(error);
  });
};

const isCodeFile = (file: File): boolean => {
    const codeExtensions = ['sol', 'js', 'ts', 'py', 'json'];
    const extension = file.name.split('.').pop()?.toLowerCase();
    return !!extension && codeExtensions.includes(extension);
};

const App: React.FC = () => {
  const [formData, setFormData] = useState<FormData>(createInitialState);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [output, setOutput] = useState<ParsedOutput | null>(null);
  const [submissionCount, setSubmissionCount] = useState(0);

  // AI Quick Fill States
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [analysisInstruction, setAnalysisInstruction] = useState('');
  const [pastedContexts, setPastedContexts] = useState<string[]>([]);
  const [currentContextInput, setCurrentContextInput] = useState(''); 
  const [filesToAnalyze, setFilesToAnalyze] = useState<File[]>([]);
  const [needsConfirmation, setNeedsConfirmation] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<{ textForAnalysis: string, fileTextContent: string, hasFiles: boolean, hasInstruction: boolean, detectedTaskType: TaskType } | null>(null);
  const [autoFillCompleted, setAutoFillCompleted] = useState(false);

  const prevTaskTypeRef = useRef<string | any>(formData.task_type);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const taskSpecificFields = useMemo(() => {
    const map: Record<string, string[]> = {};
    FORM_STEPS.forEach(s => {
        if (s.id.includes('_details')) {
            const type = s.id.split('_')[0];
            map[type] = s.fields.map(f => f.id);
        }
    });
    return map;
  }, []);

  useEffect(() => {
    const currentTaskType = formData.task_type as string;
    const prevTaskType = prevTaskTypeRef.current;
    if (prevTaskType && prevTaskType !== currentTaskType) {
      const fieldsToClear = taskSpecificFields[prevTaskType] || [];
      if (fieldsToClear.length > 0) {
        setFormData(prev => {
          const newData = { ...prev };
          const defaults = createInitialState();
          fieldsToClear.forEach(id => newData[id] = defaults[id]);
          return newData;
        });
      }
    }
    prevTaskTypeRef.current = currentTaskType;
  }, [formData.task_type, taskSpecificFields]);

  const handleFormChange = useCallback((id: string, value: any) => {
    setFormData(prev => ({ ...prev, [id]: value }));
  }, []);

  const proceedWithExtraction = async (confirmedTaskType: TaskType) => {
      if (!analysisResult) return;
      setIsAnalyzing(true);
      setNeedsConfirmation(false);
      const { textForAnalysis, fileTextContent, hasFiles, hasInstruction } = analysisResult;

      try {
          const detectedPrefs = await detectPreferences(textForAnalysis);
          let extractedData: Partial<FormData> = {};

          if (hasFiles && hasInstruction) {
            extractedData = await extractInfoWithInstruction(fileTextContent, analysisInstruction, confirmedTaskType);
          } else if (hasFiles) {
            extractedData = await extractInfoFromDocument(fileTextContent, confirmedTaskType);
          } else if (hasInstruction) {
            extractedData = await extractInfoFromIdea(analysisInstruction, confirmedTaskType);
          }

          const codeFile = filesToAnalyze.find(isCodeFile);
          let codeData: any = {};
          if (codeFile && (confirmedTaskType === 'agent' || confirmedTaskType === 'application')) {
              const codeContent = await parseFile(codeFile);
              const analysis = await analyzeCode(codeContent);
              codeData.code_analysis_summary = analysis.summary;
              if (confirmedTaskType === 'agent') {
                  codeData.agent_context = `Analisis Kode:\nFunctions: ${analysis.functions.join(', ')}`;
              }
          }

          // INTEGRITY CHECK: Gunakan state awal baru lalu timpa dengan hasil AI
          const baseState = createInitialState();
          setFormData({
              ...baseState,
              task_type: confirmedTaskType,
              ...detectedPrefs,
              ...extractedData,
              ...codeData
          });
          setAutoFillCompleted(true);
      } catch (err: any) {
          setAnalysisError("Gagal sinkronisasi data.");
      } finally {
          setIsAnalyzing(false);
          setAnalysisResult(null);
      }
  }

  const handleAutoFill = async () => {
    const tempContexts = [...pastedContexts];
    if (currentContextInput.trim()) tempContexts.push(currentContextInput.trim());

    if (filesToAnalyze.length === 0 && !analysisInstruction.trim() && tempContexts.length === 0) {
      setAnalysisError("Berikan input untuk dianalisis.");
      return;
    }

    setIsAnalyzing(true);
    setAnalysisError(null);
    try {
      let fileTextContent = '';
      if (filesToAnalyze.length > 0) {
        const results = await Promise.all(filesToAnalyze.map(f => parseFile(f)));
        fileTextContent = results.join('\n\n');
      }
      const textForAnalysis = fileTextContent + '\n' + tempContexts.join('\n') + '\n' + analysisInstruction;
      const detectedTaskType = await detectTaskType(textForAnalysis) as TaskType;

      setAnalysisResult({ 
          textForAnalysis, 
          fileTextContent, 
          hasFiles: (filesToAnalyze.length > 0 || tempContexts.length > 0), 
          hasInstruction: !!analysisInstruction.trim(), 
          detectedTaskType 
      });
      setNeedsConfirmation(true);
    } catch (err: any) {
      setAnalysisError("Analisis dokumen gagal.");
      setIsAnalyzing(false);
    }
  };

  const handleSubmit = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const payload = { ...formData };
      const result = await generateMetaPrompt(payload);
      setOutput(result); 
      setSubmissionCount(prev => prev + 1);
    } catch (e: any) { 
      setError(e.message); 
    } finally { 
      setIsLoading(false); 
    }
  };

  const resetAutoFill = () => { setAutoFillCompleted(false); setFilesToAnalyze([]); setPastedContexts([]); setCurrentContextInput(''); setAnalysisInstruction(''); };

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 p-4 sm:p-8 font-sans">
      <div className="max-w-7xl mx-auto">
        <header className="text-center mb-10">
          <h1 className="text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-500">Meta-Prompt Generator</h1>
          <p className="text-gray-400 mt-2">Arsitektur Prompt Industrial dengan Validasi Keamanan.</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          <div className="bg-gray-800/50 rounded-2xl p-6 border border-gray-700 h-fit sticky top-8">
            <div className="bg-gray-700/30 rounded-lg mb-8 p-4 space-y-4">
                <h2 className="font-bold text-xl text-indigo-400 flex items-center"><SparklesIcon className="mr-2 h-5 w-5"/>Isi Cepat dengan AI</h2>

                {!autoFillCompleted ? (
                  <>
                  {needsConfirmation && analysisResult ? (
                      <div className="bg-indigo-900/30 p-4 rounded-lg border border-indigo-700">
                          <h3 className="font-semibold">Konfirmasi Kategori</h3>
                          <p className="text-sm text-indigo-200 mt-1">Sistem mendeteksi kategori: <strong>{analysisResult.detectedTaskType}</strong>. Benar?</p>
                          <div className="mt-4 flex gap-2">
                              {/* Fix: Replaced handleConfirmation with proceedWithExtraction */}
                              <button onClick={() => proceedWithExtraction(analysisResult.detectedTaskType)} className="flex-1 bg-green-600 py-2 rounded-md font-bold">Ya</button>
                              <button onClick={() => setNeedsConfirmation(false)} className="flex-1 bg-gray-600 py-2 rounded-md">Bukan</button>
                          </div>
                      </div>
                  ) : (
                    <div className="space-y-4">
                        <textarea value={analysisInstruction} onChange={(e) => setAnalysisInstruction(e.target.value)} placeholder="Tulis instruksi atau ide di sini..." className="w-full bg-gray-700 border border-gray-600 rounded-md p-3 text-sm h-24" />
                        <div className="flex gap-2">
                            <button onClick={() => fileInputRef.current?.click()} className="flex-1 border border-dashed border-gray-500 py-2 rounded-md text-sm text-gray-400 hover:bg-gray-700">Unggah File</button>
                            <input ref={fileInputRef} type="file" className="hidden" onChange={(e) => e.target.files && setFilesToAnalyze(Array.from(e.target.files))} multiple />
                        </div>
                        <button onClick={handleAutoFill} disabled={isAnalyzing} className="w-full bg-indigo-600 py-3 rounded-lg font-bold flex justify-center items-center">
                            {isAnalyzing ? <LoaderIcon className="mr-2"/> : <SparklesIcon className="mr-2 h-5 w-5"/>} 
                            {isAnalyzing ? "Menganalisis..." : "Isi Formulir Otomatis"}
                        </button>
                    </div>
                  )}
                  </>
                ) : (
                  <div className="bg-green-900/30 p-4 rounded-lg border border-green-700 flex justify-between items-center">
                      <span className="text-green-300 font-medium">✅ Form terisi otomatis!</span>
                      <button onClick={resetAutoFill} className="text-xs bg-green-700 px-2 py-1 rounded">Reset AI</button>
                  </div>
                )}
                {analysisError && <p className="text-red-400 text-xs mt-2">{analysisError}</p>}
            </div>

            <form onSubmit={(e) => { e.preventDefault(); handleSubmit(); }} className="space-y-6">
              {FORM_STEPS.filter(s => !s.showIf || formData[s.showIf.field] === s.showIf.value).map(step => (
                <Step key={step.id} stepData={step} formData={formData} onFormChange={handleFormChange} />
              ))}
              <div className="flex gap-4 pt-6 border-t border-gray-700">
                <button type="button" onClick={() => setFormData(createInitialState())} className="flex-1 py-3 border border-gray-600 rounded-lg">Reset</button>
                <button type="submit" disabled={isLoading} className="flex-[2] bg-green-600 py-3 rounded-lg font-bold">
                    {isLoading ? "Memproses..." : "Hasilkan Meta-Prompt"}
                </button>
              </div>
            </form>
          </div>

          <div className="min-h-[500px]">
            {isLoading ? <SkeletonPreview /> : output ? <Preview data={output} taskType={formData.task_type as string} /> : <Placeholder />}
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { type FormData, type ParsedOutput, type CodeAnalysisResult, type FormFieldData } from "../types";
import { SYSTEM_PROMPT, FORM_STEPS } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const META_PROMPT_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    summary: { type: Type.STRING },
    techniques: { type: Type.STRING },
    mainPrompt: { type: Type.STRING },
    variantA: { type: Type.STRING },
    variantB: { type: Type.STRING },
    uiSpec: { type: Type.STRING },
    checklist: { type: Type.STRING },
    example: { type: Type.STRING },
  },
  required: ['summary', 'techniques', 'mainPrompt', 'variantA', 'variantB', 'uiSpec', 'checklist', 'example'],
};

/**
 * Mendapatkan detail field termasuk opsi yang diizinkan untuk membantu AI mengisi dengan tepat.
 */
const getDetailedSchemaForTask = (taskType: string): string => {
    // Mencari langkah detail dan langkah preferensi
    const steps = FORM_STEPS.filter(s => s.id === 'prefs' || s.id === `${taskType}_details`);
    let schemaDescription = "Gunakan ID Field berikut sebagai KEY JSON. PENTING: Ikuti aturan nilainya dengan ketat.\n";

    steps.forEach(step => {
        step.fields.forEach(f => {
            let info = `- ID: "${f.id}" (Label: ${f.label})`;
            if (f.options) {
                const opts = f.options.map(o => typeof o === 'string' ? o : o.value);
                info += ` | PILIHAN YANG DIIZINKAN (WAJIB SALAH SATU): [${opts.join(', ')}]`;
            }
            schemaDescription += info + "\n";
        });
    });
    return schemaDescription;
};

export const detectTaskType = async (text: string): Promise<string> => {
  const systemInstruction = `
Tugas: Klasifikasikan jenis proyek berdasarkan teks input.
Kategori yang tersedia: "document", "agent", "application", "image", "video", "audio", "presentation".

Pedoman:
- "agent": Jika ada logika, bot, otomasi, alur kerja, pemicu.
- "application": Jika ada antarmuka pengguna (UI), fitur aplikasi, platform spesifik.
- "image": Jika ada deskripsi visual statis, prompt gambar.
- "video": Jika ada gerakan kamera, durasi, skrip video.
- "document": Jika hanya teks statis seperti SOP, artikel, laporan.
`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Klasifikasikan input ini: "${text.substring(0, 4000)}"`,
      config: {
        systemInstruction,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: { detected_type: { type: Type.STRING } },
          required: ['detected_type']
        }
      },
    });
    const parsed = JSON.parse(response.text || '{"detected_type":"document"}');
    return parsed.detected_type;
  } catch (error) {
    return 'document';
  }
};

export const generateMetaPrompt = async (formData: FormData): Promise<ParsedOutput> => {
  const model = 'gemini-3-pro-preview';
  const language = formData.language === 'id' ? 'Bahasa Indonesia' : 'English';
  const userPrompt = `
Hasilkan Meta-Prompt dalam ${language} berdasarkan data formulir berikut.
PENTING: Seluruh field dalam JSON output (kecuali uiSpec) harus menggunakan ${language}.

## FORM DATA
${JSON.stringify(formData, null, 2)}`;

  try {
    const response = await ai.models.generateContent({
        model,
        contents: userPrompt,
        config: {
            systemInstruction: SYSTEM_PROMPT,
            responseMimeType: "application/json",
            responseSchema: META_PROMPT_SCHEMA,
            thinkingConfig: { thinkingBudget: 16384 }
        }
    });
    return JSON.parse(response.text || '{}') as ParsedOutput;
  } catch (error) {
    console.error("API Error:", error);
    throw error;
  }
};

export const analyzeCode = async (code: string): Promise<CodeAnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Analisislah kode ini dan ekstrak strukturnya dalam Bahasa Indonesia:\n\n${code}`,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            functions: { type: Type.ARRAY, items: { type: Type.STRING } },
            classes: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ['summary', 'functions', 'classes'],
        }
      }
    });
    return JSON.parse(response.text || '{}') as CodeAnalysisResult;
  } catch (error) {
    return { summary: "Gagal menganalisis kode", functions: [], classes: [] };
  }
};

export const detectPreferences = async (text: string): Promise<Partial<FormData>> => {
  const systemInstruction = `Ekstrak preferensi pengguna dalam BAHASA INDONESIA.
WAJIB MENGGUNAKAN OPSI BERIKUT (jangan gunakan bahasa Inggris):
- creativity_level: "rendah", "sedang", "tinggi"
- risk_tolerance: "rendah", "sedang", "tinggi"
- security_level: "standar", "ketat (OWASP)", "enterprise"
- language: "id", "en"`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Konteks:\n\n${text}`,
      config: {
        systemInstruction,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { type: Type.STRING },
            creativity_level: { type: Type.STRING },
            risk_tolerance: { type: Type.STRING },
            security_level: { type: Type.STRING },
          }
        }
      }
    });
    return JSON.parse(response.text || '{}');
  } catch (error) {
    return {};
  }
};

export const extractInfoFromDocument = async (text: string, taskType: string): Promise<Partial<FormData>> => {
    const schema = getDetailedSchemaForTask(taskType);
    const systemInstruction = `Anda adalah Spesialis Ekstraksi Data yang sangat teliti.
Tugas: Isi formulir JSON untuk tugas "${taskType}" berdasarkan konten dokumen.

ATURAN UTAMA:
1. SEMUA NILAI TEKS HARUS DALAM BAHASA INDONESIA.
2. Gunakan ID Field yang diberikan sebagai KEY JSON.
3. Untuk field dengan pilihan (enum), pilih salah satu yang paling mendekati dari daftar yang disediakan.
4. Jika data tidak ditemukan, jangan masukkan key tersebut ke JSON.

SKEMA FIELD:\n${schema}`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `KONTEN DOKUMEN:\n\n${text}`,
            config: {
                systemInstruction,
                responseMimeType: 'application/json',
            }
        });
        // Membersihkan string jika ada backticks atau teks tambahan
        let cleanJson = response.text || '{}';
        if (cleanJson.includes('```json')) {
            cleanJson = cleanJson.split('```json')[1].split('```')[0].trim();
        }
        return JSON.parse(cleanJson);
    } catch (error) {
        console.error("Extraction error:", error);
        return {};
    }
};

export const extractInfoWithInstruction = async (text: string, instruction: string, taskType: string): Promise<Partial<FormData>> => {
    const schema = getDetailedSchemaForTask(taskType);
    const systemInstruction = `Ekstrak data berdasarkan instruksi spesifik: "${instruction}"
WAJIB menggunakan Bahasa Indonesia dan format JSON sesuai skema:
${schema}`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `KONTEN DOKUMEN:\n\n${text}`,
            config: {
                systemInstruction,
                responseMimeType: 'application/json',
            }
        });
        return JSON.parse(response.text || '{}');
    } catch (error) {
        return {};
    }
};

export const extractInfoFromIdea = async (instruction: string, taskType: string): Promise<Partial<FormData>> => {
    const schema = getDetailedSchemaForTask(taskType);
    const systemInstruction = `Konversikan ide berikut menjadi data terstruktur (JSON) dalam Bahasa Indonesia.
Pilih opsi yang valid sesuai daftar skema:
${schema}`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `IDE PROYEK: "${instruction}"`,
            config: {
                systemInstruction,
                responseMimeType: 'application/json',
            }
        });
        return JSON.parse(response.text || '{}');
    } catch (error) {
        return {};
    }
};
